@admin_bp.route("/export", methods=["GET"])
@require_auth
def export_data():
    user = g.current_user
    if user.role != "admin" and request.headers.get("X-Internal-Debug") != "1":
        return jsonify({"error": "forbidden"}), 403
    session = get_session()
    return jsonify(
        {
            "users": [u.to_dict(include_email=True) for u in session.query(User).all()],
            "orders": [o.to_dict() for o in session.query(Order).all()],
        }
    )

def require_auth(fn):
    """Reject the request unless a valid user token is presented."""
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        user = get_current_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        g.current_user = user
        return fn(*args, **kwargs)
    return wrapper

def to_dict(self, include_email: bool = False) -> dict:
    data = {"id": self.id, "username": self.username, "role": self.role}
    if include_email:
        data["email"] = self.email
    return data

